component.script:
"""Files -- read, write, list and delete files in the organization's file storage.

One node runs one operation, chosen in the Inspector: READ_FILE,
READ_DIRECTORY, WRITE_FILE, WRITE_DIRECTORY, LIST or DELETE. The path is a
slash-separated path from the root of the organization's files
("reports/q3.csv") and may contain ${field} placeholders, filled from the
incoming request_data.

A misconfigured node raises ValueError before storage is touched, and a path
that does not exist raises FileNotFoundError. Nothing is written anywhere the
path did not name: a missing folder fails the run instead of falling back to
the root.
"""

import json
import re

import perceivo

_OPERATIONS = ("READ_FILE", "READ_DIRECTORY", "WRITE_FILE", "WRITE_DIRECTORY", "LIST", "DELETE")
_MAX_FILES_PER_DIRECTORY = 100
_PLACEHOLDER = re.compile(r"\$\{([\w.]+)\}")
_MIME_TYPES = {
    "txt": "text/plain",
    "md": "text/markdown",
    "csv": "text/csv",
    "json": "application/json",
    "html": "text/html",
    "xml": "application/xml",
    "yaml": "application/yaml",
    "yml": "application/yaml",
    "pdf": "application/pdf",
    "png": "image/png",
    "jpg": "image/jpeg",
    "jpeg": "image/jpeg",
    "gif": "image/gif",
    "svg": "image/svg+xml",
    "zip": "application/zip",
}


def _lookup(data, path: str):
    """Return (True, value) for a dotted path into data, or (False, None)."""
    value = data
    for part in path.split("."):
        if isinstance(value, dict) and part in value:
            value = value[part]
        elif isinstance(value, list) and part.isdigit() and int(part) < len(value):
            value = value[int(part)]
        else:
            return False, None
    return True, value


def _fill(label: str, template: str, data: dict) -> str:
    """Replace each ${path} in template with that value from data, raising on a missing field."""

    def _replace(match):
        found, value = _lookup(data, match.group(1))
        if not found:
            raise ValueError(
                f"{label} refers to ${{{match.group(1)}}}, but the incoming data has no such field."
            )
        return value if isinstance(value, str) else json.dumps(value)

    return _PLACEHOLDER.sub(_replace, template)


def _param(name: str, default: str = "") -> str:
    value = perceivo.params.get(name, default)
    return default if value is None else str(value)


def _segments(path: str) -> list:
    """The folder and file names along path; '.' and '..' are refused."""
    parts = [part.strip() for part in path.replace("\\", "/").split("/") if part.strip()]
    for part in parts:
        if part in (".", ".."):
            raise ValueError(f"File Path {path!r} uses {part!r}. Give the path from the root of the files.")
    return parts


def _mime_for(name: str) -> str:
    extension = name.rsplit(".", 1)[-1].lower() if "." in name else ""
    return _MIME_TYPES.get(extension, "application/octet-stream")


def _listing(entry) -> dict:
    return {"id": entry.id, "name": entry.name, "type": entry.entry_type, "size": entry.size_bytes}


async def _child(parent_id, name: str):
    """The entry called name directly inside parent_id (None = the root), or None."""
    for entry in await perceivo.files.list(parent_id=parent_id):
        if entry.name == name:
            return entry
    return None


async def _resolve(segments: list):
    """The entry at segments, or None when any part of the path is missing."""
    entry = None
    for name in segments:
        if entry is not None and entry.entry_type != "folder":
            return None
        entry = await _child(entry.id if entry else None, name)
        if entry is None:
            return None
    return entry


async def _folder(segments: list, path: str):
    """The id of the folder at segments (None for the root); raises when it is missing or a file."""
    if not segments:
        return None
    entry = await _resolve(segments)
    if entry is None:
        raise FileNotFoundError(f"No folder at {path!r} in the organization's files.")
    if entry.entry_type != "folder":
        raise NotADirectoryError(f"{path!r} is a file, not a folder.")
    return entry.id


async def _read(entry):
    return perceivo.primitives.Artifact(
        type=perceivo.primitives.ArtifactType.FILE,
        data=await perceivo.files.read(entry.id),
        mime_type=entry.mime_type or _mime_for(entry.name),
        file_name=entry.name,
    )


def _artifact_name(key: str, artifact) -> str:
    """The file name an incoming artifact is written under: its own, else its key."""
    if artifact.file_name:
        return artifact.file_name
    return "file.bin" if key == "main" else key


def _content_of(artifact):
    if isinstance(artifact.data, (bytes, str)):
        return artifact.data
    return json.dumps(artifact.data)


async def _write(name: str, content, folder_id, mime_type: str) -> dict:
    written = await perceivo.files.write(name, content, parent_id=folder_id, mime_type=mime_type)
    entry = written.get("entry") or {}
    return {"id": entry.get("id"), "name": entry.get("name", name), "type": "file", "size": entry.get("size_bytes")}


@perceivo.agent
async def files_agent(input: perceivo.primitives.AgentInput) -> perceivo.primitives.AgentOutput:
    """Run one file operation.

    READ_FILE and READ_DIRECTORY emit the files they read as FILE artifacts.
    Every operation puts its result on top of the incoming request_data: the
    operation, the path, file_count and, except for DELETE, a files list of
    the entries read, written or listed (id, name, type, size).
    """
    data = input.request_data or {}
    if not isinstance(data, dict):
        raise ValueError(f"request_data must be an object, not {type(data).__name__}.")

    operation = _param("operation", "READ_FILE").strip().upper()
    if operation not in _OPERATIONS:
        raise ValueError(f"Operation is {operation!r}. Choose one of: {', '.join(_OPERATIONS)}.")

    path = _fill("File Path", _param("path"), data).strip()
    segments = _segments(path)
    if not segments and operation in ("READ_FILE", "WRITE_FILE", "DELETE"):
        raise ValueError(f"File Path is empty. {operation} needs the path of a file.")

    # Everything a write needs is checked here, before storage is touched.
    if operation == "WRITE_FILE":
        if input.artifact is not None and input.artifact.data is not None:
            content = _content_of(input.artifact)
        else:
            content = _fill("Content", _param("content"), data)
            if not content:
                raise ValueError("WRITE_FILE needs an incoming file or some Content to write.")
    elif operation == "WRITE_DIRECTORY":
        incoming = {}
        if input.artifacts:
            incoming = {key: a for key, a in input.artifacts.items() if a is not None and a.data is not None}
        if not incoming and input.artifact is not None and input.artifact.data is not None:
            incoming = {"main": input.artifact}
        if not incoming:
            raise ValueError("WRITE_DIRECTORY needs at least one incoming file.")

    passthrough = dict(data)
    perceivo.log.info(f"Files: {operation}", operation=operation, path=path)
    artifacts = []

    if operation == "READ_FILE":
        entry = await _resolve(segments)
        if entry is None:
            raise FileNotFoundError(f"No file at {path!r} in the organization's files.")
        if entry.entry_type == "folder":
            raise IsADirectoryError(f"{path!r} is a folder. Use READ_DIRECTORY to read its files.")
        artifacts = [await _read(entry)]
        result = {**passthrough, "operation": operation, "path": path, "file_count": 1, "files": [_listing(entry)]}
    elif operation == "READ_DIRECTORY":
        entries = [e for e in await perceivo.files.list(parent_id=await _folder(segments, path))
                   if e.entry_type != "folder"]
        entries = sorted(entries, key=lambda e: e.name)[:_MAX_FILES_PER_DIRECTORY]
        artifacts = [await _read(entry) for entry in entries]
        listed = [_listing(entry) for entry in entries]
        result = {**passthrough, "operation": operation, "path": path, "file_count": len(listed), "files": listed}
    elif operation == "WRITE_FILE":
        folder_id = await _folder(segments[:-1], "/".join(segments[:-1]))
        written = await _write(segments[-1], content, folder_id, _mime_for(segments[-1]))
        result = {**passthrough, "operation": operation, "path": path, "file_count": 1, "files": [written]}
    elif operation == "WRITE_DIRECTORY":
        folder_id = await _folder(segments, path)
        listed = []
        for key, artifact in incoming.items():
            name = _artifact_name(key, artifact)
            mime_type = _mime_for(name) if artifact.mime_type in (None, "", "text/plain") else artifact.mime_type
            listed.append(await _write(name, _content_of(artifact), folder_id, mime_type))
        result = {**passthrough, "operation": operation, "path": path, "file_count": len(listed), "files": listed}
    elif operation == "LIST":
        entries = await perceivo.files.list(parent_id=await _folder(segments, path))
        listed = sorted((_listing(e) for e in entries), key=lambda item: (item["type"] != "folder", item["name"]))
        result = {**passthrough, "operation": operation, "path": path, "file_count": len(listed), "files": listed}
    else:
        entry = await _resolve(segments)
        if entry is None:
            raise FileNotFoundError(f"No file or folder at {path!r} in the organization's files.")
        await perceivo.files.delete(entry.id)
        result = {**passthrough, "operation": operation, "path": path, "file_count": 0}

    if not artifacts:
        return perceivo.primitives.AgentOutput(artifact=None, response_data=result)
    # The first file read is the main artifact; READ_DIRECTORY also emits every file it read, by name.
    return perceivo.primitives.AgentOutput(
        artifact=artifacts[0],
        artifacts={a.file_name: a for a in artifacts} if operation == "READ_DIRECTORY" else {},
        response_data=result,
    )
